using System;using System.Linq;using System.Collections.Generic;using UnityEngine;
namespace Groundworks.FuelFire {
public class FuelFX {
 static readonly Queue<float> sparkTimes=new Queue<float>();public static readonly List<FuelFX> Active=new List<FuelFX>();public GameObject root;public ParticleSystem jet,vapor,flame,core,smoke;public Light light;static Material mistMat,fireMat;public float Scale;public bool VisibleFlame;public bool ready;GameObject wetPatch;Mesh wetMesh;
 public static FuelFX Create(Transform parent,Vector3 localPoint,Vector3 direction){int limit=FuelRuntime.Quality==0?8:FuelRuntime.Quality==2?32:16;if(Active.Count>=limit)return null;EnsureMaterials();if(mistMat==null||fireMat==null)return null;var f=new FuelFX();f.root=new GameObject("GW fuel leak and fire");f.root.transform.SetParent(parent,false);f.root.transform.localPosition=localPoint;f.root.transform.localRotation=Quaternion.LookRotation(direction.sqrMagnitude<.001f?Vector3.forward:direction);f.jet=f.System("Liquid droplets",mistMat,true);f.vapor=f.System("Fuel vapour",mistMat,false);f.flame=f.System("Fuel flame",fireMat,true);f.core=f.System("Flame hot core",fireMat,true);f.smoke=f.System("Fuel smoke",mistMat,false);f.light=new GameObject("Fuel fire light").AddComponent<Light>();f.light.transform.SetParent(f.root.transform,false);f.light.type=LightType.Point;f.light.shadows=LightShadows.None;f.light.enabled=false;f.ready=true;Active.Add(f);return f;}
 static void EnsureMaterials(){if(mistMat!=null&&fireMat!=null)return;Shader alpha=Shader.Find("Legacy Shaders/Particles/Alpha Blended")??Shader.Find("Particles/Alpha Blended");Shader additive=Shader.Find("KSP/Particles/Additive")??Shader.Find("Particles/Additive");if(alpha==null||additive==null)return;var texture=new Texture2D(64,64,TextureFormat.RGBA32,false);var pixels=new Color[4096];for(int y=0;y<64;y++)for(int x=0;x<64;x++){float r=new Vector2((x-31.5f)/31.5f,(y-31.5f)/31.5f).magnitude;float a=Mathf.Pow(Mathf.Clamp01(1-r),1.7f);pixels[y*64+x]=new Color(1,1,1,a);}texture.SetPixels(pixels);texture.Apply();mistMat=new Material(alpha);mistMat.name="GW original fluid mist";mistMat.mainTexture=texture;fireMat=new Material(additive);fireMat.name="GW original fuel flame";fireMat.mainTexture=texture;}
 ParticleSystem System(string name,Material material,bool stretched){var go=new GameObject(name);go.transform.SetParent(root.transform,false);var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.playOnAwake=false;m.loop=true;m.simulationSpace=ParticleSystemSimulationSpace.World;m.maxParticles=FuelRuntime.Quality==0?200:FuelRuntime.Quality==2?1800:700;m.startLifetime=.6f;m.startSize=.04f;m.startSpeed=3;var e=ps.emission;e.rateOverTime=0;var sh=ps.shape;sh.shapeType=ParticleSystemShapeType.Cone;sh.angle=12;sh.radius=.018f;var color=ps.colorOverLifetime;color.enabled=true;var g=new Gradient();g.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(.7f,0),new GradientAlphaKey(.4f,.6f),new GradientAlphaKey(0,1)});color.color=new ParticleSystem.MinMaxGradient(g);var rr=go.GetComponent<ParticleSystemRenderer>();rr.sharedMaterial=material;if(stretched){rr.renderMode=ParticleSystemRenderMode.Stretch;rr.velocityScale=.10f;rr.lengthScale=1.5f;}FloatingOrigin.RegisterParticleSystem(ps);ps.Play();return ps;}
 static void Configure(ParticleSystem ps,float rate,float size,float speed,float life,Color color){var m=ps.main;m.startSize=size;m.startSpeed=speed;m.startLifetime=life;m.startColor=color;var e=ps.emission;e.rateOverTime=Mathf.Max(0,rate);}
 public void Refresh(FuelReservoir reservoir,Vector3 up,bool gas,bool pool){if(root==null)return;if(pool)root.transform.rotation=Quaternion.LookRotation(up.sqrMagnitude<.1f?Vector3.up:up);UpdateWetPatch(reservoir,pool&&!gas);float flow=(float)reservoir.LastLeakKgS,burn=(float)reservoir.LastBurnKgS;Scale=FuelReservoir.VisualScale(burn);VisibleFlame=burn>1e-7f;float quality=FuelRuntime.Quality==0?.45f:FuelRuntime.Quality==2?1.4f:1;float amount=Mathf.Clamp(Mathf.Sqrt(Mathf.Max(0,flow)),0,12);float cloud=Mathf.Clamp((float)Math.Sqrt(reservoir.CloudKg),0,10);float flicker=.88f+.08f*Mathf.Sin(Time.time*13+root.GetInstanceID()*.19f)+.06f*Mathf.Sin(Time.time*23+root.GetInstanceID()*.11f);Configure(jet,gas?0:Mathf.Min(220,amount*28*quality),.012f+amount*.006f,pool?1:2+amount*.8f,.8f,new Color(.78f,.79f,.67f,.7f));Configure(vapor,Mathf.Min(180,(amount*(gas?22:7)+cloud*5)*quality),.08f+amount*.035f,pool?.6f:1+amount*.3f,1.5f,new Color(.80f,.83f,.86f,.23f));foreach(var ps in new[]{flame,core,smoke})ps.transform.rotation=Quaternion.LookRotation(up.sqrMagnitude<.1f?Vector3.up:up);Color outer=reservoir.FlameColor;outer.a=.32f;Configure(flame,VisibleFlame?Mathf.Min(260,32*Mathf.Sqrt(burn)*quality)*flicker:0,.10f+Scale*.40f,Scale*2.5f,.25f+Scale*.45f,outer);Configure(core,VisibleFlame?Mathf.Min(190,10*Mathf.Sqrt(burn)*quality)*flicker:0,.05f+Scale*.20f,Scale*3,.15f+Scale*.25f,new Color(1,.84f,.42f,.30f));Configure(smoke,VisibleFlame?Mathf.Min(230,25*Mathf.Sqrt(burn)*reservoir.Smoke*quality):0,.16f+Scale*.65f,Scale*1.2f,2.7f,new Color(.11f,.10f,.09f,.24f));light.enabled=VisibleFlame;light.color=outer;light.intensity=VisibleFlame?Mathf.Clamp(Mathf.Log(1+burn)*.6f,.05f,3)*flicker:0;light.range=1+Scale*4;}
 void UpdateWetPatch(FuelReservoir reservoir,bool pool){if(!pool||reservoir.LiquidRemainingKg<.001){if(wetPatch!=null)wetPatch.SetActive(false);return;}if(wetPatch==null){wetPatch=new GameObject("Finite liquid wet patch");wetPatch.transform.SetParent(root.transform,false);wetPatch.transform.localPosition=new Vector3(0,0,-.025f);wetMesh=new Mesh();wetMesh.vertices=new[]{new Vector3(-1,-1,0),new Vector3(1,-1,0),new Vector3(1,1,0),new Vector3(-1,1,0)};wetMesh.triangles=new[]{0,2,1,0,3,2};wetMesh.uv=new[]{new Vector2(0,0),new Vector2(1,0),new Vector2(1,1),new Vector2(0,1)};bool fuel=reservoir.slots.Any(s=>s.profile.kind==FluidKind.Fuel);Color c=fuel?new Color(.10f,.065f,.025f,.5f):new Color(.03f,.06f,.08f,.35f);wetMesh.colors=new[]{c,c,c,c};wetMesh.RecalculateBounds();wetPatch.AddComponent<MeshFilter>().sharedMesh=wetMesh;wetPatch.AddComponent<MeshRenderer>().sharedMaterial=mistMat;}wetPatch.SetActive(true);float radius=Mathf.Clamp(.12f+.035f*Mathf.Sqrt((float)reservoir.LiquidRemainingKg),.12f,3);wetPatch.transform.localScale=new Vector3(radius*1.25f,radius*.85f,1);}
 public IEnumerable<Renderer> Renderers{get{return root==null?Enumerable.Empty<Renderer>():root.GetComponentsInChildren<Renderer>();}}
 public void Dispose(){if(root!=null){foreach(var p in root.GetComponentsInChildren<ParticleSystem>())FloatingOrigin.UnregisterParticleSystem(p);UnityEngine.Object.Destroy(root);}if(wetMesh!=null)UnityEngine.Object.Destroy(wetMesh);wetPatch=null;wetMesh=null;root=null;ready=false;Active.Remove(this);}
 public static void Sparks(Vector3 position,Vector3 direction,float strength){while(sparkTimes.Count>0&&Time.time-sparkTimes.Peek()>1)sparkTimes.Dequeue();if(sparkTimes.Count>=12)return;sparkTimes.Enqueue(Time.time);EnsureMaterials();if(fireMat==null)return;var go=new GameObject("GW impact ignition sparks");go.transform.position=position;go.transform.rotation=Quaternion.LookRotation(direction.sqrMagnitude<.001f?Vector3.up:direction);var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.loop=false;m.playOnAwake=false;m.startLifetime=.18f;m.startSpeed=3+Mathf.Clamp(strength,0,4);m.startSize=.018f;m.startColor=new Color(1,.62f,.20f,.8f);m.simulationSpace=ParticleSystemSimulationSpace.World;m.maxParticles=40;var e=ps.emission;e.enabled=false;var s=ps.shape;s.shapeType=ParticleSystemShapeType.Cone;s.angle=50;var r=go.GetComponent<ParticleSystemRenderer>();r.sharedMaterial=fireMat;r.renderMode=ParticleSystemRenderMode.Stretch;r.velocityScale=.15f;r.lengthScale=2;FloatingOrigin.RegisterParticleSystem(ps);go.AddComponent<FuelParticleLifetime>().system=ps;ps.Emit(FuelRuntime.Quality==0?8:24);UnityEngine.Object.Destroy(go,1);}
}
}
